gaaF(){return"\u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633\u060c \u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u0627\u0646 \u0648 \u0645\u0627\u062f\u062f\u06d5\u06a9\u0627\u0646 \u2014 \u06af\u06c6\u0695\u0627\u0646\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0633\u062a\u0628\u06d5\u062c\u06ce \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0634\u0648\u06ce\u0646\u06ce\u06a9 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0628\u0646."},
gaaE(){return"\u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u0627\u0646"},
gQG(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0642\u06c6\u0646\u0627\u063a"},
ga9W(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u0642\u06c6\u0646\u0627\u063a"},
ga9Y(){return" \xb7 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646"},
gaag(){return"\u0628\u06c6 \u067e\u06ce\u0634\u06d5\u0648\u06d5 \u0628\u06af\u0648\u0627\u0632\u06d5\u0631\u06d5\u0648\u06d5"},
gaaf(){return"\u0628\u06c6 \u062f\u0648\u0627\u0648\u06d5 \u0628\u06af\u0648\u0627\u0632\u06d5\u0631\u06d5\u0648\u06d5"},
gaaD(){return"\u0646\u0627\u0648"},
gaaC(){return"\u0695\u06d5\u0646\u06af (\u0647\u06ce\u06a9\u0633\u060c \u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 FFB8763F)"},
ga9A(){return"\u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633"},
gQB(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
ga9S(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
