ga9y(){return"\u0698\u0645\u0627\u0631\u06d5\u06cc \u0695\u06c6\u0698\u06cc \u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc \u0628\u06c6 \u0628\u06d5\u0631\u0648\u0627\u0631\u06cc \u06af\u06d5\u06cc\u0634\u062a\u0646"},
ga9x(){return"\u0628\u06c6 \u067e\u06ce\u0634\u0646\u06cc\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u0628\u06d5\u0631\u0648\u0627\u0631\u06cc \u06af\u06d5\u06cc\u0634\u062a\u0646 \u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9\u06cc \u0646\u0648\u06ce \u0644\u06d5\u0645 \u062c\u06c6\u0631\u06d5 \u062f\u0631\u0648\u0633\u062a \u062f\u06d5\u06a9\u0631\u06ce\u062a \u0628\u06d5\u06a9\u0627\u0631\u062f\u06ce\u062a \u2014 \u0647\u06d5\u0645\u06cc\u0634\u06d5 \u062f\u06d5\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0628\u06c6 \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0628\u06af\u06c6\u0695\u062f\u0631\u06ce\u062a."},
ga9z(){return"\u0695\u06d5\u0646\u06af\u06cc \u0628\u06d5\u06a9\u0627\u0631\u062f\u06d5\u0647\u06ce\u0646\u06ce\u062a"},
ga9u(){return"\u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0648\u06ce \u0628\u06d5 \u0634\u06ce\u0648\u06d5\u06cc\u06d5\u06a9\u06cc \u062e\u06c6\u06a9\u0627\u0631 \u0695\u06ce\u0695\u06d5\u0648\u06cc \u0628\u06d5\u0631\u0647\u06d5\u0645\u0647\u06ce\u0646\u0627\u0646\u06cc \u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f\u06cc \u0666 \u0642\u06c6\u0646\u0627\u063a\u06cc \u0648\u06d5\u0631\u062f\u06d5\u06af\u0631\u06ce\u062a (\u0644\u06d5\u06af\u06d5\u06b5 \u0644\u06cc\u0633\u062a\u06d5\u06cc \u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f\u06cc \u0661\u0666 \u0695\u06d5\u0646\u06af \u0626\u06d5\u06af\u06d5\u0631 \u0695\u06d5\u0646\u06af\u06cc \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0628\u06ce\u062a) \u2014 \u0647\u06d5\u0631\u062f\u0648\u0648\u06a9\u06cc\u0627\u0646 \u062f\u0648\u0627\u062a\u0631 \u062f\u06d5\u06af\u06c6\u0695\u062f\u0631\u06ce\u0646."},
ga9t(){return"\u067e\u06cc\u06a9\u0648\u0631\u062a\u06d5\u06a9\u0631\u0627\u0648\u06d5 (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
ga9s(){return"\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5: CR"},
gQJ(){return"\u0646\u0627\u0686\u0627\u0644\u0627\u06a9"},
ga9I(){return"\u06a9\u06c6\u0645\u0628\u06c6\u06a9\u0627\u0646"},
ga9H(){return"\u067e\u06ce\u0634\u06d5\u06a9\u06cc\u06cc \u0626\u0627\u0645\u0627\u062f\u06d5\u06a9\u0631\u0627\u0648 \u0628\u06c6 \u062c\u06c6\u0631\u06d5 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5 \u067e\u06ce\u06a9\u06d5\u0648\u06d5 \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0627\u0648 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 \u0626\u06cc\u0645\u067e\u0644\u0627\u0646\u062a + \u062a\u0627\u062c) \u2014 \u06cc\u06d5\u06a9\u06ce\u06a9\u06cc\u0627\u0646 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5 \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0648\u06ce \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646 \u06cc\u06d5\u06a9\u062c\u0627\u0631 \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u0631\u06ce\u0646."},
ga9q(){return"\u0695\u06ce\u06af\u06d5 \u0628\u06d5 \u0647\u06d5\u06b5\u0628\u0698\u0627\u0631\u062f\u0646\u06cc \u0626\u0627\u0632\u0627\u062f \u0628\u062f\u06d5"},
ga9r(){return"\u0647\u06d5\u0631\u0648\u06d5\u0647\u0627 \u0695\u06ce\u06af\u06d5 \u0628\u062f\u06d5 \u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0648\u06ce \u0628\u06d5 \u0626\u0627\u0632\u0627\u062f\u06cc \u0647\u06d5\u0631 \u06a9\u06c6\u0645\u06d5\u06b5\u06ce\u06a9 \u0644\u06d5 \u062c\u06c6\u0631\u06d5 \u0686\u0627\u0644\u0627\u06a9\u06d5\u06a9\u0627\u0646 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06ce\u062a\u060c \u0647\u06d5\u0631\u06cc\u06d5\u06a9\u06d5 \u0644\u06d5\u06af\u06d5\u06b5 \u06a9\u06d5\u0631\u06d5\u0633\u062a\u06d5/\u0695\u06d5\u0646\u06af\u06cc \u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc \u062e\u06c6\u06cc \u062e\u0648\u0627\u0631\u06d5\u0648\u06d5 \u2014 \u0646\u06d5\u06a9 \u062a\u06d5\u0646\u0647\u0627 \u067e\u06ce\u0634\u06d5\u06a9\u06cc\u06cc\u06d5 \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646\u06cc \u0633\u06d5\u0631\u06d5\u0648\u06d5."},
gQK(){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc \u0628\u06c6 \u0626\u06d5\u0645 \u062c\u06c6\u0631\u06d5 \u2014 \u06cc\u06d5\u06a9\u06d5\u0645 \u062c\u0627\u0631 \u0628\u06d5\u06a9\u0627\u0631\u062f\u06ce\u062a \u06a9\u0627\u062a\u06ce\u06a9 \u0626\u06d5\u0645 \u062c\u06c6\u0631\u06d5 \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0648\u06ce\u062f\u0627 \u0647\u06d5\u06b5\u062f\u06d5\u0628\u0698\u06ce\u0631\u062f\u0631\u06ce\u062a"},
gQC(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u06a9\u06c6\u0645\u0628\u06c6"},
ga9T(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u06a9\u06c6\u0645\u0628\u06c6"},
gaah(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u06a9\u06c6\u0645\u0628\u06c6\u06cc\u06d5\u06a9 \u0646\u06cc\u06cc\u06d5."},
gaab(){return"\u0626\u0627\u0633\u062a\u06d5\u06a9\u0627\u0646\u06cc \u0646\u0631\u062e"},
gaaa(){return'\u062a\u0627\u06af\u06cc \u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5 \u0648\u06d5\u06a9 "\u0626\u0627\u0633\u0627\u06cc\u06cc"/"\u067e\u0631\u06ce\u0645\u06cc\u06c6\u0645" \u06a9\u06d5 \u0645\u0627\u062f\u062f\u06d5\u06cc\u06d5\u06a9 \u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0647\u06d5\u06b5\u0628\u06af\u0631\u06ce\u062a \u2014 \u062f\u0648\u0648 \u06cc\u0627\u0646 \u0632\u06cc\u0627\u062a\u0631 \u0645\u0627\u062f\u062f\u06d5 \u0628\u06c6 \u0647\u06d5\u0645\u0627\u0646 \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633 \u0628\u06d5 \u062c\u06cc\u0627\u0648\u0627\u0632\u06cc \u062a\u0627\u06af \u0628\u06a9\u06d5 \u0628\u06c6 \u067e\u06ce\u0634\u06a9\u06d5\u0634\u06a9\u0631\u062f\u0646\u06cc \u0644\u06cc\u0633\u062a\u06cc \u0646\u0631\u062e\u06cc \u062f\u0648\u0648\u06d5\u0645 \u0628\u06d5\u0628\u06ce \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u062e\u0648\u062f\u06cc \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u06d5.'},
gQH(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0626\u0627\u0633\u062a"},
ga9X(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u0626\u0627\u0633\u062a"},
gaai(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u0626\u0627\u0633\u062a\u06ce\u06a9 \u0646\u06cc\u06cc\u06d5 \u2014 \u0645\u0627\u062f\u062f\u06d5\u06a9\u0627\u0646 \u0628\u06d5 \u0647\u06d5\u0645\u0627\u0646 \u0634\u06ce\u0648\u06d5\u06cc \u067e\u06ce\u0634\u0648\u0648 \u06a9\u0627\u0631\u062f\u06d5\u06a9\u06d5\u0646 \u0647\u06d5\u062a\u0627 \u06cc\u06d5\u06a9\u06ce\u06a9 \u0632\u06cc\u0627\u062f \u0628\u06a9\u06d5\u06cc\u062a."},
